// MQTT topic: safe/<cam>/alert —— 工地安全监控统一告警通道
//   event=unsafe 着装违规 / event=smoke 烟雾；其它前缀一律丢弃
var parts = msg.topic.split("/");
var kind = parts[0] || "";
if (kind !== "safe") { return null; }
var dev = (parts[1] || "cam1").replace(/[^a-zA-Z0-9_-]/g, "_");
var data = msg.payload;
if (typeof data === "string") { try { data = JSON.parse(data); } catch (e) { data = {}; } }
if (!data || typeof data !== "object") { data = {}; }
var evt = data.event || "alert";
var ts = (data.ts_ip && String(data.ts_ip).indexOf(".") >= 0) ? String(data.ts_ip) : "127.0.0.1";
var IMG_BASE = "http://127.0.0.1:8092/";
var imgName = data.image ? String(data.image).split("/").pop() : null;
var vidName = data.video ? String(data.video).split("/").pop() : null;
var title = (evt === "smoke") ? "烟雾告警" : (evt === "unsafe") ? "安全着装告警" : "安全告警";
var lines = [];
if (data.time) { lines.push("时间: " + data.time); }
if (data.camera_id) { lines.push("点位: " + data.camera_id); }
if (evt === "smoke") { if (data.level) { lines.push("浓度: " + data.level); } if (data.ao_raw !== undefined && data.ao_raw !== null) { lines.push("AO 原始值: " + data.ao_raw); } if (data.do !== undefined) { lines.push("DO 电平: " + data.do); } }
else { if (data.unsafe !== undefined || data.partial !== undefined) { lines.push("完全违规(帽衣都没): " + (data.unsafe || 0) + " 人; 部分违规: " + (data.partial || 0) + " 人"); } if (data.persons && data.persons.length) { var det = []; for (var i = 0; i < Math.min(data.persons.length, 6); i++) { var p = data.persons[i]; det.push("#" + (p.track_id == null ? (i + 1) : p.track_id) + " " + p.status + "(帽" + Number(p.helmet_conf || 0).toFixed(2) + "/衣" + Number(p.vest_conf || 0).toFixed(2) + ")"); } lines.push("人员: " + det.join(", ")); } }
if (imgName) { lines.push("截图: http://" + ts + ":8092/" + imgName); }
if (vidName) { lines.push("录像: http://" + ts + ":8092/" + vidName); }
var payload = { topic: "safe_" + dev, title: title, message: lines.join("\n") || "检测到告警", priority: 4 };
if (imgName) { payload.attach = IMG_BASE + imgName; payload.click = "http://" + ts + ":8092/" + imgName; }
payload.actions = [{ action: "view", label: "查看实时画面", url: "http://" + ts + ":8090/" }];
msg.payload = payload;
msg.headers = { "content-type": "application/json" };
return msg;

// safe/<cam>/status：检测服务/摄像头状态
var parts = msg.topic.split("/");
var kind = parts[0] || "";
if (kind !== "safe") { return null; }
var dev = (parts[1] || "cam1").replace(/[^a-zA-Z0-9_-]/g, "_");
var data = msg.payload;
if (typeof data === "string") { try { data = JSON.parse(data); } catch (e) { data = {}; } }
if (!data || typeof data !== "object") { data = {}; }
var ts = (data.ts_ip && String(data.ts_ip).indexOf(".") >= 0) ? String(data.ts_ip) : "127.0.0.1";
var evt = (data.event === "startup") ? "系统启动，安全监控已运行" : (data.event === "reconnect") ? "摄像头重连成功" : (data.event === "camera_lost") ? "摄像头未连接，请检查 USB / 设备节点" : "设备状态更新";
var title = (data.event === "camera_lost") ? "摄像头未连接" : "摄像头已连接";
var priority = (data.event === "camera_lost") ? 3 : 2;
var payload = { topic: "safe_" + dev, title: title, message: evt + (data.time ? "（" + data.time + "）" : ""), priority: priority, actions: [{ action: "view", label: "查看实时画面", url: "http://" + ts + ":8090/" }] };
msg.payload = payload;
msg.headers = { "content-type": "application/json" };
return msg;
